        ph_coords.x2 -= right + border_width;
        ph_coords.y1 += top + border_width;
        ph_coords.y2 -= bottom + border_width;
        ph_dsc.text = ta->placeholder_txt;
        lv_draw_label(layer, &ph_dsc, &ph_coords);
    }
